mapper.sql:
WHERE r.deleted = 0

    AND r.customer_id = #{forcedCustomerId}


    AND r.status = #{q.status}


    AND r.category = #{q.category}


    AND (r.ticket_no LIKE CONCAT(#{q.keyword}, '%') OR r.title LIKE CONCAT(#{q.keyword}, '%'))


    AND r.created_at >= #{q.fromTime}


    AND r.created_at <= #{q.toTime}

mapper.update:
UPDATE repair_ticket
SET status = #{target}, version = version + 1, updated_at = #{now}
WHERE id = #{id} AND deleted = 0 AND status = #{expected}
